export const empty=()=>({version:1,materials:[],suppliers:[],purchases:[],entries:[],proposals:[],employees:[],steps:[],audit:[],quotes:[]});export class LocalRepository{load(){let raw=localStorage.getItem('rr-elvira-v1');return raw?this.validate(JSON.parse(raw)):empty()}validate(s){if(s.version!==1||Object.keys(empty()).some(k=>k!=='version'&&!Array.isArray(s[k])))throw Error('Backup incompatível');return s}save(s){localStorage.setItem('rr-elvira-v1',JSON.stringify(s))}}